        if (c == null) {
            throw new IllegalArgumentException("Character to encode must not be null");
        }

        // If the caller supplied an immunity list, honor it first
        if (immune != null) {
            for (char immuneChar : immune) {
                if (immuneChar == c.charValue()) {
                    return String.valueOf(c);
