import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a unique name derived from {@code name}.
     * The method protects against directory‑traversal attacks by normalising the supplied
     * filename and ensuring that the resulting path stays within {@code dir}. It also
     * removes any query component and guarantees that the file name does not contain
     * absolute paths or path separators.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain a query string)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code name} is null, empty, or resolves to an
     *                                  invalid path
     * @throws SecurityException        if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory cannot be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name cannot be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths
        if (new File(name).isAbsolute()) {
            throw new SecurityException("Absolute paths are not allowed: " + name);
        }

        // Remove leading path separators
        name = name.replaceAll("^[/\\\\]+", "");
        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name cannot be empty after sanitisation");
        }

        try {
            // Canonicalise the base directory
            File canonicalDir = dir.getCanonicalFile();
            Path dirPath = canonicalDir.toPath();

            // Resolve and normalise the target path
            Path targetPath = dirPath.resolve(name).normalize();
            if (!targetPath.startsWith(dirPath)) {
                throw new SecurityException("Directory traversal attempt detected: " + name);
            }

            File file = targetPath.toFile();

            // Handle duplicate names
            int dot = name.indexOf('.');
            String prefix = dot < 0 ? name : name.substring(0, dot);
            String suffix = dot < 0 ? "" : name.substring(dot);
            int index = 2;
            while (file.exists()) {
                String newName = prefix + "-" + index++ + suffix;
                targetPath = dirPath.resolve(newName).normalize();
                if (!targetPath.startsWith(dirPath)) {
                    throw new SecurityException("Directory traversal attempt detected during renaming");
                }
                file = targetPath.toFile();
            }

            // Ensure parent directories exist
            File parent = file.getParentFile();
            if (parent != null && !parent.exists()) {
                if (!parent.mkdirs()) {
                    throw new IOException("Failed to create directories: " + parent);
                }
            }

            return file;
        } catch (IOException e) {
            // Wrap checked exception into unchecked to preserve original method signature
            throw new RuntimeException("Failed to allocate file", e);
        }
    }

    // other methods

}
```

