private Stream<MapResult> xmlXpathToMapResult(@Name("url") String url, boolean simpleMode, String path, Map<String, Object> config) throws Exception {
    if (config == null) config = Collections.emptyMap();
    boolean failOnError = Boolean.TRUE.equals(config.getOrDefault("failOnError", true));
    List<MapResult> result = new ArrayList<>();

    try {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // secure settings
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);
        dbf.setNamespaceAware(true);
        dbf.setIgnoringElementContentWhitespace(true);
        dbf.setValidating(false);
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        DocumentBuilder builder = dbf.newDocumentBuilder();

        @SuppressWarnings("unchecked")
        Map<String, Object> headers = (Map<String, Object>) config.getOrDefault("headers", Collections.emptyMap());

        try (InputStream is = Util.openInputStream(url, headers, null)) {
            Document doc = builder.parse(is);
            XPathFactory xpf = XPathFactory.newInstance();
            XPath xpath = xpf.newXPath();
            String xpathExpr = StringUtils.isEmpty(path) ? "/" : path;
            XPathExpression expr = xpath.compile(xpathExpr);
            NodeList nodes = (NodeList) expr.evaluate(doc, XPathConstants.NODESET);
            for (int i = 0; i < nodes.getLength(); i++) {
                Deque<Map<String, Object>> stack = new LinkedList<>();
                handleNode(stack, nodes.item(i), simpleMode);
                while (!stack.isEmpty()) {
                    result.add(new MapResult(stack.pollFirst()));
                }
            }
        }
    } catch (Exception e) {
        if (!failOnError) {
            return Stream.of(new MapResult(Collections.emptyMap()));
        }
        throw e;
    }
    return result.stream();
}

