private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                Object principal,
                                                Object credentials) throws NamingException {
    if (principal == null || credentials == null) {
        throw new IllegalArgumentException("Principal and credentials must not be null");
    }

    JndiLdapContextFactory jndi = (JndiLdapContextFactory) ldapContextFactory;
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndi.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndi.getUrl());

    LdapContext ctx = null;
    try {
        /* 1️⃣ Create an anonymous context so that the initial bind is not sent over
           plaintext. */
        ctx = new InitialLdapContext(env, null);

        /* 2️⃣ Negotiate STARTTLS.  The TLS handshake must succeed before we
           send any credentials. */
        StartTlsRequest tlsReq = new StartTlsRequest();
        StartTlsResponse tlsResp = (StartTlsResponse) ctx.extendedOperation(tlsReq);
        tlsResp.negotiate(); // throws IOException on failure

        /* 3️⃣ Re‑bind with the supplied credentials over the secured channel.
           DirContext.reconnect() performs a fresh bind using the supplied
           environment. */
        Hashtable<String, Object> authEnv = new Hashtable<>();
        authEnv.put(Context.SECURITY_AUTHENTICATION, jndi.getAuthenticationMechanism());
        authEnv.put(Context.SECURITY_PRINCIPAL, principal);
        authEnv.put(Context.SECURITY_CREDENTIALS, credentials);
        ctx.reconnect(authEnv);

        /* 4️⃣ Perform a lightweight lookup to force the server to validate
           the credentials immediately.  If authentication fails, a NamingException
           will be thrown. */
        ctx.lookup("");

        return ctx;
    } catch (IOException e) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm(
                "Failed to negotiate TLS connection with '%s': %s",
                server(jndi),
                e.getMessage()));
        throw new CommunicationException(e.getMessage(), e);
    } catch (NamingException e) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm(
                "LDAP authentication failed for '%s' on '%s': %s",
                principal,
                server(jndi),
                e.getMessage()));
        throw e;
    } catch (Throwable t) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm(
                "Unexpected error establishing secure LDAP connection to '%s': %s",
                server(jndi),
                t.getMessage()));
        throw t;
    }
}
