public class Expander {

    // other methods

    /**
     * Safely extracts archive entries into {@code targetDirectory}.  The method
     * performs rigorous path validation to prevent path‑traversal attacks.
     *
     * @param supplier      supplies archive entries to be extracted
     * @param writer        writes the data of an entry to an {@link OutputStream}
     * @param targetDirectory the root directory where entries are extracted
     * @throws IOException if extraction fails or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory once to its real (canonical) path.
        final Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            final String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name.
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has an empty name");
            }

            // Reject absolute paths and paths that resolve to the root or parent.
            Path entryPath = Paths.get(entryName);
            if (entryPath.isAbsolute()
                    || entryPath.equals(Paths.get("."))
                    || entryPath.equals(Paths.get(".."))) {
                throw new IOException("archive entry contains an absolute or disallowed path: "
                        + entryName);
            }

            // Resolve the entry against the target directory and normalize.
            Path resolvedPath = targetDirPath.resolve(entryPath).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + entryName
                        + " would create file outside of " + targetDirectory);
            }

            File f = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist.
                Path parentPath = resolvedPath.getParent();
                if (parentPath != null) {
                    Files.createDirectories(parentPath);
                }

                // Write the file contents.
                try (OutputStream out = Files.newOutputStream(
                        resolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
