public String getValidHref(String url) {
    if (!StringUtils.isNotBlank(url)) {
        return "";
    }
    try {
        URI uri = new URI(url.trim());
        String scheme = uri.getScheme();
        if (scheme == null || !isAllowedScheme(scheme)) {
            return "";
        }
        // Rebuild URI to ensure proper encoding
        URI normalized = new URI(
                scheme,
                uri.getUserInfo(),
                uri.getHost(),
                uri.getPort(),
                uri.getPath(),
                uri.getQuery(),
                uri.getFragment()
        );
        String sanitized = normalized.toASCIIString();

        // Escape problematic characters
        sanitized = sanitized.replace("\"", "%22")
                             .replace("'", "%27")
                             .replace("<", "%3C")
                             .replace(">", "%3E")
                             .replace("`", "%60");

        if (xssFilter.isValidHref(sanitized)) {
            return sanitized;
        }
    } catch (URISyntaxException e) {
        LOGGER.warn("Invalid URL syntax: {}", url, e);
    }
    return "";
}

private boolean isAllowedScheme(String scheme) {
    return "http".equalsIgnoreCase(scheme) ||
           "https".equalsIgnoreCase(scheme) ||
           "mailto".equalsIgnoreCase(scheme);
}
